function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => v < 1 || v > 100)) return 'Each value is between 1 and 100.';
  if (k < 1 || k > 100) return 'k is between 1 and 100.';
  return null;
}

