function minOperations(nums, k) {
  // Breadth-first search over whole arrays, trying every h below the current maximum.
  const goal = nums.map(() => k).join();
  const seen = new Set([nums.join()]);
  let frontier = [nums];
  for (let steps = 0; frontier.length > 0; steps++) {
    const next = [];
    for (const state of frontier) {
      if (state.join() === goal) return steps;
      const top = Math.max(...state);
      for (let h = 0; h < top; h++) {
        const bigger = state.filter(v => v > h);
        if (bigger.some(v => v !== bigger[0])) continue;
        const after = state.map(v => Math.min(v, h));
        if (!seen.has(after.join())) { seen.add(after.join()); next.push(after); }
      }
    }
    frontier = next;
  }
  return -1;
}

