function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const large = size === 'large';
  const top = large ? 100 : 1 + pick(10);
  const n = large ? 100 : 1 + pick(6);
  const k = 1 + pick(top);
  // Half of the inputs keep every value at least k, so -1 is not the usual answer.
  const low = rand() < 0.5 ? k : 1;
  const nums = Array.from({ length: n }, () => low + pick(top - low + 1));
  return [nums, k];
}
